create table academic_mobilities (date_from date, date_to date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), country varchar(255), created_by varchar(255), description TEXT, document_url TEXT, institution TEXT, notes TEXT, program_name TEXT, updated_by varchar(255), primary key (id));
create table achievements (date_achieved date, qualified_count integer, verified boolean not null, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, achievement_type varchar(255) check (achievement_type in ('PP_1_PUBLICATIONS','PP_2_PATENTS','PP_3_TEXTBOOK','PP_4_METHODICAL','PP_5_DISSERTATION','PP_6_SUPERVISION','PP_7_ATTESTATION','PP_8_EDITORIAL','PP_9_EXPERT_COUNCIL','PP_10_INTERNATIONAL','PP_11_CONSULTING','PP_12_APPROBATION','PP_13_FOREIGN_LANGUAGE','PP_14_STUDENT_OLYMPIAD','PP_15_SCHOOL_OLYMPIAD','PP_16_COMBAT_VETERAN','PP_17_UN_PEACEKEEPING','PP_18_NATO_EXERCISES','PP_19_PROFESSIONAL_ASSOCIATIONS','PP_20_PRACTICAL_EXPERIENCE')), description TEXT, document_url varchar(255), notes TEXT, title varchar(255), verified_by varchar(255), primary key (id));
create table attestation_activity (count integer, defense_date date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), council_name varchar(255), created_by varchar(255), document_url TEXT, role varchar(255) check (role in ('OPPONENT','COUNCIL_MEMBER','SPORADIC_COUNCIL')), student_name varchar(255), updated_by varchar(255), primary key (id));
create table career_records (end_date date, start_date date, id bigint generated by default as identity, teacher_id bigint, notes TEXT, organization varchar(255), position varchar(255), primary key (id));
create table departments (faculty_id bigint, id bigint generated by default as identity, name varchar(255), number varchar(255), primary key (id));
create table discipline_documents (deadline date, discipline_id bigint, id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), file_url varchar(255), notes TEXT, status varchar(255) check (status in ('DRAFT','REVIEW','APPROVED')), type varchar(255), primary key (id));
create table disciplines (auditory_hours integer, credits float(53), hours_group integer, hours_lab integer, hours_lecture integer, hours_practical integer, hours_self_study integer, total_hours integer, department_id bigint, educational_program_id bigint, id bigint generated by default as identity, code varchar(255), control_types TEXT, credit_semesters varchar(255), credits_by_semester TEXT, exam_semesters varchar(255), hours_by_semester TEXT, name varchar(255), primary key (id));
create table docx_export_templates (header_row_count integer, table_index integer, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), column_mappings_json TEXT, name varchar(255), original_file_name varchar(255), template_file_name varchar(255), primary key (id));
create table docx_templates (created_at timestamp(6), created_by bigint, id bigint generated by default as identity, updated_at timestamp(6), description varchar(255), name varchar(255), template_config TEXT, primary key (id));
create table editorial_activity (date_from date, date_to date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), created_by varchar(255), description TEXT, document_url TEXT, journal_or_project_name TEXT, role varchar(255) check (role in ('THEME_LEADER','RESPONSIBLE_EXECUTOR','CHIEF_EDITOR','BOARD_MEMBER','REVIEWER')), updated_by varchar(255), primary key (id));
create table editorial_plan_items (actual_date date, planned_date date, id bigint generated by default as identity, plan_id bigint, teacher_id bigint, status varchar(255) check (status in ('PLANNED','IN_PROGRESS','COMPLETED','OVERDUE')), title varchar(255), type varchar(255), primary key (id));
create table editorial_plans (created_at timestamp(6), department_id bigint, id bigint generated by default as identity, uploaded_by bigint, academic_year varchar(255), file_url varchar(255), title varchar(255), primary key (id));
create table educational_programs (credits integer, enrollment_year integer, created_at timestamp(6), department_id bigint, id bigint generated by default as identity, updated_at timestamp(6), degree varchar(255), duration varchar(255), education_form varchar(255), education_level varchar(255), educational_qualification varchar(255), field_of_knowledge varchar(255), name varchar(255) not null, professional_qualification varchar(255), short_code varchar(255), specialization TEXT, specialty varchar(255), primary key (id));
create table educations (diploma_date date, graduation_year integer, id bigint generated by default as identity, teacher_id bigint not null, city varchar(255), degree varchar(255), diploma TEXT, institution TEXT, qualification TEXT, speciality TEXT, primary key (id));
create table expert_council (date_from date, date_to date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), council_name varchar(255), created_by varchar(255), document_url TEXT, order_number varchar(255), role varchar(255), type varchar(255) check (type in ('MON','NAZYAVO','ACCREDITATION','NMR','STATE_SERVICE')), updated_by varchar(255), primary key (id));
create table faculties (id bigint generated by default as identity, name varchar(255), primary key (id));
create table fakhovi_journals (inclusion_date date, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), category varchar(255) check (category in ('CATEGORY_A','CATEGORY_B')), founders TEXT, name TEXT, name_normalized TEXT, specialty_codes TEXT, primary key (id));
create table file_attachments (entity_id bigint not null, file_size bigint, id bigint generated by default as identity, uploaded_at timestamp(6), entity_type varchar(50) not null, mime_type varchar(100) not null, local_path varchar(500), original_name varchar(500) not null, drive_file_id varchar(255), uploaded_by varchar(255), primary key (id));
create table foreign_language_teaching (hours integer, semester integer, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), academic_year varchar(255), created_by varchar(255), discipline_name varchar(255), document_url TEXT, language varchar(255), updated_by varchar(255), primary key (id));
create table gantt_events (end_date date, semester integer, start_date date, id bigint generated by default as identity, teacher_id bigint, academic_year varchar(255), color varchar(255), event_type varchar(255), notes TEXT, status varchar(255), title varchar(255), primary key (id));
create table international_project (date_from date, date_to date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), created_by varchar(255), description TEXT, document_url TEXT, program varchar(255) check (program in ('ERASMUS','HORIZON','NATO','BILATERAL','GRANT','OTHER')), project_name TEXT, role varchar(255), updated_by varchar(255), primary key (id));
create table language_skills (certificate_date date, smr1 integer, smr2 integer, smr3 integer, smr4 integer, id bigint generated by default as identity, teacher_id bigint, certificate_number varchar(200), certificate_organization varchar(300), certificate_url varchar(500), certificate_details varchar(255), language varchar(255), level varchar(255), primary key (id));
create table methodological_experiments (date date, order_date date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), created_by varchar(255), description TEXT, document_url TEXT, notes TEXT, order_number varchar(255), title TEXT, updated_by varchar(255), primary key (id));
create table military_educations (diploma_date date, graduation_year integer, id bigint generated by default as identity, teacher_id bigint not null, issued_by varchar(500), diploma TEXT, institution TEXT, level varchar(255) check (level in ('OPERATIONAL','STRATEGIC')), speciality TEXT, primary key (id));
create table military_mission (date_from date, date_to date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), country varchar(255), created_by varchar(255), document_url TEXT, mission_name varchar(255), mission_type varchar(255) check (mission_type in ('UN_PEACEKEEPING','NATO_EXERCISE')), updated_by varchar(255), primary key (id));
create table notifications (is_read boolean not null, created_at timestamp(6), id bigint generated by default as identity, user_id bigint, link_url varchar(255), message TEXT, title varchar(255), type varchar(255), primary key (id));
create table olympiad_guidance (competition_year integer, order_date date, participant_count integer, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), academic_year varchar(255), activity_type varchar(255) check (activity_type in ('OLYMPIAD','SCIENTIFIC_COMPETITION','COMPETITION','SCIENTIFIC_GROUP','SPORTS','ARTS','OTHER')), competition_name varchar(255), competition_scope varchar(255) check (competition_scope in ('INTERNATIONAL','NATIONAL')), created_by varchar(255), department_name varchar(255), description TEXT, document_url TEXT, level varchar(255) check (level in ('STUDENT','SCHOOL')), olympiad_name varchar(255), order_number varchar(255), result varchar(255), role varchar(255) check (role in ('SUPERVISOR','JURY','COMMITTEE','GROUP_LEADER','COACH','CURATOR')), student_name varchar(255), updated_by varchar(255), primary key (id));
create table open_lessons (date date, order_date date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), created_by varchar(255), document_url TEXT, host_department varchar(255), lesson_type varchar(255), notes TEXT, order_number varchar(255), topic TEXT, updated_by varchar(255), primary key (id));
create table ppdata_validation_results (pp_number integer not null, entity_id bigint, id bigint generated by default as identity, teacher_id bigint, validated_at timestamp(6), entity_summary TEXT, entity_type varchar(255), pp_label varchar(255), reasoning TEXT, session_id varchar(255), status varchar(255), primary key (id));
create table practical_experience (date_from date, date_to date, years_count integer, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), created_by varchar(255), document_url TEXT, organization_name varchar(255), position varchar(255), specialty_name varchar(255), updated_by varchar(255), primary key (id));
create table professional_association (date_from date, date_to date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), certificate_number varchar(255), created_by varchar(255), document_url TEXT, organization_name varchar(255), role varchar(255), updated_by varchar(255), primary key (id));
create table program_working_groups (order_date date, created_at timestamp(6), id bigint generated by default as identity, program_id bigint not null, teacher_id bigint not null, updated_at timestamp(6), order_number varchar(255), role varchar(255) check (role in ('CHAIR','MEMBER')), primary key (id));
create table protocol_settings (id bigint generated by default as identity, settings_json TEXT, primary key (id));
create table publications (author_sheet_count float(53), field_relevant boolean, publication_year integer, total_pages integer, achievement_id bigint, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), source_section varchar(20), isbn varchar(30), issn varchar(30), publisher varchar(500), approbation_subtype varchar(255) check (approbation_subtype in ('SCOPUS_WOS','INTERNATIONAL','DOMESTIC')), article_category varchar(255) check (article_category in ('SCOPUS','WOS','CATEGORY_A','CATEGORY_B')), authors TEXT, city varchar(255), conference_info TEXT, created_by varchar(255), document_url TEXT, doi varchar(255), dstu_citation TEXT, journal_name TEXT, methodical_subtype varchar(255) check (methodical_subtype in ('PRACTICUM','METHODICAL_GUIDELINES','E_COURSE','LECTURE_NOTES','WORK_PROGRAM')), pages varchar(255), pp_type varchar(255) check (pp_type in ('PP_1_PUBLICATIONS','PP_2_PATENTS','PP_3_TEXTBOOK','PP_4_METHODICAL','PP_5_DISSERTATION','PP_6_SUPERVISION','PP_7_ATTESTATION','PP_8_EDITORIAL','PP_9_EXPERT_COUNCIL','PP_10_INTERNATIONAL','PP_11_CONSULTING','PP_12_APPROBATION','PP_13_FOREIGN_LANGUAGE','PP_14_STUDENT_OLYMPIAD','PP_15_SCHOOL_OLYMPIAD','PP_16_COMBAT_VETERAN','PP_17_UN_PEACEKEEPING','PP_18_NATO_EXERCISES','PP_19_PROFESSIONAL_ASSOCIATIONS','PP_20_PRACTICAL_EXPERIENCE')), raw_text TEXT, status varchar(255) check (status in ('NOT_VALIDATED','AI_VALIDATED','NEEDS_ATTENTION','HEAD_VALIDATED','OUTDATED')), title TEXT, type varchar(255) check (type in ('ARTICLE','PATENT','DECLARATIVE_PATENT','COPYRIGHT','TEXTBOOK','STUDY_GUIDE','MONOGRAPH','METHODICAL','APPROBATION','POPULAR_SCIENTIFIC','OTHER')), updated_by varchar(255), url TEXT, volume varchar(255), primary key (id));
create table qualification_improvements (certificate_date date, credits float(53), end_date date, hours integer, start_date date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, category varchar(255) check (category in ('GENERAL','MILITARY_COURSE')), certificate_number varchar(255), certificate_url varchar(255), country varchar(255), military_course_level varchar(255) check (military_course_level in ('L2','L3','L4')), organization varchar(255), title varchar(255), primary key (id));
create table rating_periods (active boolean not null, end_date date, start_date date, created_at timestamp(6), id bigint generated by default as identity, name varchar(255), primary key (id));
create table scientific_consulting (date_from date, date_to date, years_count integer, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), contract_number varchar(255), created_by varchar(255), document_url TEXT, organization_name varchar(255), updated_by varchar(255), primary key (id));
create table scientific_supervision (defense_date date, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, updated_at timestamp(6), created_by varchar(255), degree_type varchar(255) check (degree_type in ('PHD','DSC','CANDIDATE','DOCTOR')), diploma_number varchar(255), document_url TEXT, student_name varchar(255), topic TEXT, updated_by varchar(255), primary key (id));
create table scopus_journals (created_at timestamp(6), id bigint generated by default as identity, eissn varchar(30), issn varchar(30), name TEXT, name_normalized TEXT, primary key (id));
create table staff_positions (order_number integer, rate float(53), tariff_grade integer, department_id bigint not null, id bigint generated by default as identity, teacher_id bigint, imported_teacher_name varchar(255), military_rank_category varchar(255), military_specialty_code varchar(255), position_title varchar(255), primary key (id));
create table teacher_compliance_cache (achievement_count integer not null, degree_matches_department boolean not null, diploma_matches_department boolean not null, publications_count integer not null, qualification_matches_department boolean not null, relevant_publications_count integer not null, unique_type_count integer not null, ai_last_computed_at timestamp(6), teacher_id bigint not null, updated_at timestamp(6) not null, status varchar(32) not null check (status in ('COMPLIANT','WARNING','NON_COMPLIANT','EXEMPT')), exemption_reason varchar(500), achievement_types TEXT, missing_info TEXT, primary key (teacher_id));
create table teacher_discipline_match_cache (fully_compliant boolean not null, has_dissertation_supervision boolean not null, has_matching_degree boolean not null, has_matching_diploma boolean not null, has_practical_experience boolean not null, point36compliant boolean not null, point37a_compliant boolean not null, point37b_compliant boolean not null, point37compliant boolean not null, qualified_publications_count integer not null, ai_last_computed_at timestamp(6), discipline_id bigint not null, id bigint generated by default as identity, teacher_id bigint not null, updated_at timestamp(6) not null, primary key (id), constraint uq_tdmc_teacher_discipline unique (teacher_id, discipline_id));
create table teacher_disciplines (semester integer, discipline_id bigint, id bigint generated by default as identity, teacher_id bigint, academic_year varchar(255), primary key (id));
create table teacher_program_match_cache (has_dissertation_supervision boolean not null, has_matching_degree boolean not null, has_matching_diploma boolean not null, has_practical_experience boolean not null, point37a_compliant boolean not null, point37b_compliant boolean not null, point37compliant boolean not null, qualified_publications_count integer not null, ai_last_computed_at timestamp(6), id bigint generated by default as identity, program_id bigint not null, teacher_id bigint not null, updated_at timestamp(6) not null, primary key (id), constraint uq_tpmc_teacher_program unique (teacher_id, program_id));
create table teacher_ratings (count integer not null, score integer not null, calculated_at timestamp(6), id bigint generated by default as identity, period_id bigint not null, teacher_id bigint not null, criterion varchar(255) not null check (criterion in ('SCOPUS_ARTICLE','WOS_ARTICLE','CATEGORY_A_ARTICLE','CATEGORY_B_ARTICLE','PATENT','DECLARATIVE_PATENT','COPYRIGHT','TEXTBOOK','MONOGRAPH','STUDY_GUIDE','PRACTICUM','METHODICAL_GUIDELINES','E_COURSE','LECTURE_NOTES','DOCTORAL_DEFENSE','PHD_DEFENSE','DOCTORAL_SUPERVISION','PHD_SUPERVISION','OFFICIAL_OPPONENT','COUNCIL_MEMBER','ONE_TIME_REVIEWER','EDITORIAL_BOARD','EXPERT_COUNCIL','INTERNATIONAL_PROJECT','SCIENTIFIC_CONSULTING','APPROBATION_SCOPUS','APPROBATION_INTERNATIONAL','APPROBATION_DOMESTIC','FOREIGN_LANGUAGE_TEACHING','OLYMPIAD_INTERNATIONAL_PRIZE','OLYMPIAD_NATIONAL_PRIZE','SCIENCE_GROUP_LEADER','COMBAT_VETERAN','COMBAT_EXPERIENCE','UN_PEACEKEEPING','NATO_EXERCISES','PROFESSIONAL_ASSOCIATION','PROFESSOR_TITLE','DOCENT_TITLE','QUALIFICATION_CREDIT','FOREIGN_INTERNSHIP','OPEN_LESSON','METHODOLOGICAL_EXPERIMENT','ACADEMIC_MOBILITY','WORKING_GROUP_CHAIR','WORKING_GROUP_MEMBER','SMR_LEVEL_1','SMR_LEVEL_2','SMR_LEVEL_3','MILITARY_COURSE_3_6','MILITARY_COURSE_6_10','MILITARY_COURSE_10_PLUS','MILITARY_ED_OPERATIONAL','MILITARY_ED_STRATEGIC')), details TEXT, primary key (id), unique (period_id, teacher_id, criterion));
create table teachers (birth_year integer, combat_veteran_doc_date date, combat_veteran_status boolean not null, degree_diploma_date date, experience_start_date date, military_education_diploma_date date, title_attestat_date date, university_diploma_date date, university_graduation_year integer, created_at timestamp(6), department_id bigint, id bigint generated by default as identity, updated_at timestamp(6), combat_veteran_doc_issued_by varchar(500), military_education_issued_by varchar(500), academic_degree varchar(255), academic_title varchar(255), combat_experience_dates varchar(255), combat_veteran_doc varchar(255), degree_diploma varchar(255), dissertation_speciality TEXT, dissertation_topic TEXT, email varchar(255), employment_type varchar(255), first_name varchar(255), google_scholar_url varchar(255), last_name varchar(255), military_education_diploma varchar(255), military_education_level varchar(255) check (military_education_level in ('OPERATIONAL','STRATEGIC')), military_rank varchar(255), notes TEXT, orcid_id varchar(255), patronymic varchar(255), phone varchar(255), photo_url varchar(255), position TEXT, scopus_id varchar(255), title_attestat varchar(255), university TEXT, university_diploma TEXT, university_speciality TEXT, wos_id varchar(255), primary key (id));
create table users (is_active boolean not null, created_at timestamp(6), id bigint generated by default as identity, teacher_id bigint, email varchar(255) not null unique, password_hash varchar(255), role varchar(255) not null check (role in ('ADMIN','HEAD_OF_DEPARTMENT','TEACHER')), primary key (id));
